import { createReadStream, type ReadStream } from 'node:fs';
import { mkdir, readFile, stat, writeFile } from 'node:fs/promises';
import path from 'node:path';

/**
 * Local file storage rooted at a single directory (a Docker volume shared by
 * the API and the worker). Paths are always generated by the application;
 * resolve() additionally refuses anything that escapes the root.
 */
export class LocalFileStorage {
  private readonly root: string;

  constructor(rootDir: string) {
    this.root = path.resolve(rootDir);
  }

  get rootDir(): string {
    return this.root;
  }

  resolve(relativePath: string): string {
    const normalized = relativePath.replace(/\\/g, '/');
    if (normalized.startsWith('/') || normalized.split('/').includes('..')) {
      throw new Error('Invalid storage path');
    }
    const absolute = path.resolve(this.root, normalized);
    if (absolute !== this.root && !absolute.startsWith(this.root + path.sep)) {
      throw new Error('Invalid storage path');
    }
    return absolute;
  }

  async save(relativePath: string, content: Buffer): Promise<void> {
    const absolute = this.resolve(relativePath);
    await mkdir(path.dirname(absolute), { recursive: true });
    // 'wx' fails if the file exists: stored documents are never overwritten.
    await writeFile(absolute, content, { flag: 'wx', mode: 0o640 });
  }

  async read(relativePath: string): Promise<Buffer> {
    return readFile(this.resolve(relativePath));
  }

  createReadStream(relativePath: string): ReadStream {
    return createReadStream(this.resolve(relativePath));
  }

  async exists(relativePath: string): Promise<boolean> {
    try {
      await stat(this.resolve(relativePath));
      return true;
    } catch {
      return false;
    }
  }
}
